        ok("Monocraft" in pg.eval_on_selector("#cw .rmk text", "e=>getComputedStyle(e).fontFamily"), f"{w}px Item: Marker in Pixel-Schrift", pg.eval_on_selector("#cw .rmk text", "e=>getComputedStyle(e).fontFamily"))
